# Python implementation
import asyncio
import random
import time
from dataclasses import dataclass
from typing import Callable, TypeVar, Any

@dataclass
class RateLimitConfig:
    max_retries: int = 5
    base_delay: float = 1.0
    max_delay: float = 60.0
    jitter_factor: float = 0.2

T = TypeVar('T')

class RateLimitedClient:
    def __init__(
        self,
        model: Any,
        config: RateLimitConfig = None,
        rpm: int = 60
    ):
        self.model = model
        self.config = config or RateLimitConfig()
        self.rpm = rpm
        self.tokens = rpm
        self.last_refill = time.time()
        self._lock = asyncio.Lock()
    
    def _refill_tokens(self):
        now = time.time()
        elapsed = now - self.last_refill
        refill_amount = int(elapsed * (self.rpm / 60))
        
        if refill_amount > 0:
            self.tokens = min(self.rpm, self.tokens + refill_amount)
            self.last_refill = now
    
    async def _acquire_token(self):
        while self.tokens <= 0:
            self._refill_tokens()
            if self.tokens <= 0:
                await asyncio.sleep(1)
        
        self.tokens -= 1
    
    def _calculate_backoff(self, attempt: int) -> float:
        delay = self.config.base_delay * (2 ** attempt)
        jitter = delay * self.config.jitter_factor * random.random()
        return min(delay + jitter, self.config.max_delay)
    
    def _is_rate_limit_error(self, error: Exception) -> bool:
        return any(code in str(error) for code in ['429', 'RESOURCE_EXHAUSTED', 'quota'])
    
    async def with_retry(
        self,
        operation: Callable[..., T],
        *args,
        **kwargs
    ) -> T:
        last_error = None
        
        for attempt in range(self.config.max_retries + 1):
            try:
                await self._acquire_token()
                return await operation(*args, **kwargs)
            except Exception as e:
                last_error = e
                
                if self._is_rate_limit_error(e):
                    delay = self._calculate_backoff(attempt)
                    print(f"Rate limit hit, retrying in {delay:.2f}s...")
                    await asyncio.sleep(delay)
                    continue
                
                raise
        
        raise last_error
