    def _register_builtin_tools(self):
        """Register built-in tools."""
        
        # Weather tool
        async def get_weather(args: Dict[str, Any]) -> Dict[str, Any]:
            location = args.get("location", "")
            units = args.get("units", "celsius")
            
            # Mock weather API
            return {
