                        },
                        "max_results": {
                            "type": "number",
                            "description": "Số kết quả tối đa"
                        }
                    },
                    "required": ["query"]
                },
                handler=lambda args: {"results": []}
            ),
        ]
        
        config = AgentConfig(
            max_iterations=10,
            verbose=True,
            system_prompt="""Bạn là một AI assistant thông minh có thể sử dụng các tools để trả lời câu hỏi.
            
            Các tools có sẵn:
            - get_weather: Lấy thời tiết
